/**
 * Race flow — ported from WaveKill: odometer progress, gate milestones, wrong-way.
 * Open world: no corridor clamp; gates are route markers only.
 */

import { Vector3 } from 'three';
import { CONFIG } from '../core/config';
import { clamp } from '../core/mathx';
import type { GameContext, Racer, RacePhase, Subsystem, TrackPoint } from '../core/types';
import type { Track } from './track';
import { resetHull } from '../ship/hull';
import { stepShip } from '../ship/shipPhysics';
import { syncShipTransform } from '../ship/ship';

const _tp: TrackPoint = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};

interface RacerProgress {
  lastU: number;
  lapDistance: number;
  lapStartTime: number;
  wrongTimer: number;
  furthest: number;
}

export class RaceStateSystem implements Subsystem {
  readonly name = 'raceState';
  readonly order = 50;

  private progressData = new Map<number, RacerProgress>();
  private countdown = CONFIG.race.countdownSeconds;
  private goFlash = 0;
  private finishOrder: Racer[] = [];

  init(ctx: GameContext) {
    this.reset(ctx);
  }

  private reset(ctx: GameContext) {
    this.countdown = CONFIG.race.countdownSeconds;
    this.goFlash = 0;
    this.finishOrder = [];
    ctx.phase = 'countdown';
    ctx.raceTime = -CONFIG.race.countdownSeconds;
    this.progressData.clear();

    const track = ctx.track as Track;
    for (let i = 0; i < ctx.racers.length; i++) {
      const r = ctx.racers[i];
      const grid = track.startGrid(i);
      r.state.position.copy(grid.position);
      r.state.position.y = CONFIG.ship.hoverHeight + grid.position.y;
      r.state.velocity.set(0, 0, 0);
      r.state.heading = grid.heading;
      r.state.boostMeter = 0.4;
      resetHull(r.hull);
      r.destroyed = false;
      r.root.visible = true;
      r.root.scale.setScalar(1);
      r.state.hp = r.hull.hp;
      r.state.maxHp = r.hull.maxHp;
      r.state.hitFlash = 0;
      r.state.pitch = 0;
      r.state.roll = 0;
      r.state.weapon = 'none';
      r.state.weaponAmmo = 0;
      r.state.nitroTime = 0;
      r.lap = 0;
      r.nextCheckpoint = 1;
      r.finished = false;
      r.finishTime = 0;
      r.lapTimes = [];
      r.bestLap = Infinity;
      r.wrongWay = false;
      syncShipTransform(r);

      const proj = track.project(r.state.position);
      const signed = (((proj.u + 0.5) % 1) - 0.5) * track.length;
      this.progressData.set(r.id, {
        lastU: proj.u,
        lapDistance: signed,
        lapStartTime: 0,
        wrongTimer: 0,
        furthest: signed,
      });
      r.progress = signed / track.length;
    }
    this.assignPlaces(ctx);
  }

  update(ctx: GameContext) {
    if (ctx.phase === 'countdown') {
      this.countdown -= ctx.dt;
      ctx.raceTime = -this.countdown;
      // WaveKill: clear controls + kill residual surge until lights go green.
      for (const r of ctx.racers) {
        r.controls.throttle = 0;
        r.controls.brake = 0;
        r.controls.steer = 0;
        r.controls.boost = false;
        r.controls.airbrakeL = false;
        r.controls.airbrakeR = false;
        r.controls.firePressed = false;
        r.controls.nitroPressed = false;
        r.state.velocity.set(0, 0, 0);
        r.state.nitroTime = 0;
        r.state.appliedThrottle = 0;
        r.state.boosting = false;
        syncShipTransform(r);
      }
      if (this.countdown <= 0) {
        ctx.phase = 'racing';
        ctx.raceTime = 0;
        this.goFlash = 1.2;
      }
      return;
    }

    if (ctx.phase === 'results' || ctx.phase === 'finished') {
      for (const r of ctx.racers) syncShipTransform(r);
      if (this.goFlash > 0) this.goFlash -= ctx.dt;
      // Promote after the finish / wreck beat — must live here, not only on the
      // racing path, or goFlash never expires into results and Race Again never shows.
      if (ctx.phase === 'finished' && this.goFlash <= 0) {
        ctx.phase = 'results';
      }
      return;
    }

    ctx.raceTime += ctx.dt;
    if (this.goFlash > 0) this.goFlash -= ctx.dt;

    // Player physics (AI system steps AI craft)
    const player = ctx.player;
    if (!player.finished && !player.destroyed) {
      stepShip(player.state, player.controls, ctx.track, ctx.dt, {
        combat: ctx.combat,
        hull: player.hull,
      });
      syncShipTransform(player);
    } else {
      syncShipTransform(player);
    }

    for (const r of ctx.racers) {
      if (r.finished || r.destroyed) continue;
      this.updateProgress(ctx, r);
    }
    this.assignPlaces(ctx);

    if ((player.finished || player.destroyed) && ctx.phase === 'racing') {
      if (player.destroyed && this.goFlash <= 0) this.goFlash = 1.6;
      ctx.phase = 'finished';
    }
    if (ctx.phase === 'finished') {
      // promote after short beat via goFlash reuse
      if (this.goFlash <= 0) ctx.phase = 'results';
    }
  }

  private updateProgress(ctx: GameContext, r: Racer) {
    const track = ctx.track as Track;
    const d = this.progressData.get(r.id);
    if (!d) return;

    const proj = track.project(r.state.position);
    let du = proj.u - d.lastU;
    if (du > 0.5) du -= 1;
    if (du < -0.5) du += 1;
    d.lastU = proj.u;
    d.lapDistance += du * track.length;
    if (d.lapDistance > d.furthest) d.furthest = d.lapDistance;
    r.progress = r.lap + d.lapDistance / track.length;

    this.updateWrongWay(ctx, r, d, proj.u);
    this.advanceGates(ctx, r, d);
  }

  private updateWrongWay(ctx: GameContext, r: Racer, d: RacerProgress, u: number) {
    const v = r.state.velocity;
    const speed = Math.hypot(v.x, v.z);
    let align = 1;
    if (speed > 0.4) {
      (ctx.track as Track).sample(u, _tp);
      align = (v.x * _tp.tangent.x + v.z * _tp.tangent.z) / speed;
    }
    const bad = speed > 4.5 && align < CONFIG.race.wrongWayDot;
    d.wrongTimer = clamp(d.wrongTimer + (bad ? ctx.dt : -ctx.dt * 2.5), 0, 1.4);
    r.wrongWay = d.wrongTimer > 0.55;
  }

  private advanceGates(ctx: GameContext, r: Racer, d: RacerProgress) {
    const track = ctx.track as Track;
    const cps = track.checkpoints;
    for (let guard = 0; guard <= cps.length; guard++) {
      const idx = r.nextCheckpoint;
      if (idx === 0) {
        if (d.lapDistance < track.length) break;
        this.completeLap(ctx, r, d);
        if (r.finished) return;
        continue;
      }
      const milestone = cps[idx].s;
      if (d.lapDistance < milestone) break;
      r.nextCheckpoint = (idx + 1) % cps.length;
      if (r.isPlayer) ctx.audio?.checkpoint();
    }
    for (let guard = 0; guard <= cps.length; guard++) {
      const idx = r.nextCheckpoint;
      const prev = (idx - 1 + cps.length) % cps.length;
      if (prev === 0) break;
      const milestone = cps[prev].s;
      if (d.lapDistance >= milestone - 10) break;
      r.nextCheckpoint = prev;
    }
  }

  private completeLap(ctx: GameContext, r: Racer, d: RacerProgress) {
    const lapTime = ctx.raceTime - d.lapStartTime;
    d.lapStartTime = ctx.raceTime;
    d.lapDistance -= (ctx.track as Track).length;
    d.furthest = d.lapDistance;
    r.nextCheckpoint = 1;
    r.lapTimes.push(lapTime);
    if (lapTime < r.bestLap) r.bestLap = lapTime;
    r.lap++;
    if (r.isPlayer) ctx.audio?.playLap();

    if (r.lap >= CONFIG.race.laps) {
      if (r.destroyed) return;
      r.finished = true;
      r.finishTime = ctx.raceTime;
      this.finishOrder.push(r);
      r.place = this.finishOrder.length;
      if (r.isPlayer) {
        ctx.audio?.playFinish();
        this.goFlash = 1.5;
      }
    }
  }

  private assignPlaces(ctx: GameContext) {
    // Exploded ships are out of the classement — rank only living craft.
    const living = ctx.racers.filter((r) => !r.destroyed && r.state.hp > 0);
    const finishers = living
      .filter((r) => r.finished)
      .sort((a, b) => a.finishTime - b.finishTime);
    const racing = living
      .filter((r) => !r.finished)
      .sort((a, b) => b.progress - a.progress);

    let place = 1;
    for (const r of finishers) r.place = place++;
    for (const r of racing) r.place = place++;
    for (const r of ctx.racers) {
      if (r.destroyed || r.state.hp <= 0) r.place = Number.MAX_SAFE_INTEGER;
    }
  }

  getCountdown() {
    return this.countdown;
  }
  getGoFlash() {
    return this.goFlash;
  }

  restart(ctx: GameContext) {
    this.reset(ctx);
  }
}
