/**
 * Mobile / touch overlay styles — Hotline neon pads, safe-area aware.
 * Imported once from main so Vite bundles it.
 */

const css = /* css */ `
#touch {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}
#touch .touch-safe {
  position: absolute;
  inset: 0;
  padding:
    max(8px, env(safe-area-inset-top))
    max(10px, env(safe-area-inset-right))
    max(10px, env(safe-area-inset-bottom))
    max(10px, env(safe-area-inset-left));
  pointer-events: none;
}
#touch .touch-steer,
#touch .touch-btn,
#touch .touch-air {
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
}
#touch .touch-steer {
  position: absolute;
  left: max(10px, env(safe-area-inset-left));
  bottom: max(12px, env(safe-area-inset-bottom));
  width: min(36vw, 148px);
  height: min(36vw, 148px);
  border-radius: 50%;
  background: rgba(22, 22, 31, 0.5);
  border: 2px solid rgba(30, 240, 240, 0.55);
  box-shadow: 0 0 0 1px rgba(255, 61, 154, 0.25) inset;
}
#touch .touch-steer-ring {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  border: 1px solid rgba(30, 240, 240, 0.28);
  pointer-events: none;
}
#touch .touch-steer-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 38%;
  height: 38%;
  border-radius: 50%;
  background: rgba(30, 240, 240, 0.85);
  border: 2px solid rgba(18, 8, 28, 0.9);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 16px rgba(30, 240, 240, 0.45);
  pointer-events: none;
}
#touch .touch-label {
  position: absolute;
  left: 0; right: 0; bottom: 8%;
  text-align: center;
  font: 700 9px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.22em;
  color: rgba(242, 251, 255, 0.7);
  pointer-events: none;
}
#touch .touch-air {
  position: absolute;
  left: max(10px, env(safe-area-inset-left));
  bottom: calc(max(12px, env(safe-area-inset-bottom)) + min(36vw, 148px) + 8px);
  display: flex;
  gap: 6px;
}
#touch .touch-air-btn {
  width: 56px;
  height: 40px;
  font-size: 10px;
  min-height: 40px;
  border-radius: 8px;
}
#touch .touch-actions {
  position: absolute;
  right: max(8px, env(safe-area-inset-right));
  bottom: max(10px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(2, minmax(64px, 16vw));
  grid-template-areas:
    "brake brake"
    "boost fire"
    "nitro cam";
  gap: 6px;
  pointer-events: none;
}
#touch .touch-btn {
  pointer-events: auto;
  appearance: none;
  border: 2px solid rgba(255, 61, 154, 0.7);
  background: rgba(22, 22, 31, 0.58);
  color: #f2fbff;
  font: 800 11px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.12em;
  border-radius: 10px;
  min-height: 48px;
  padding: 0 6px;
  text-transform: uppercase;
}
#touch .touch-brake {
  grid-area: brake;
  min-height: 52px;
  border-color: rgba(255, 90, 90, 0.85);
  color: #ffc2c2;
}
#touch .touch-boost {
  grid-area: boost;
  border-color: rgba(255, 61, 139, 0.9);
  color: #ffb0d8;
}
#touch .touch-fire {
  grid-area: fire;
  border-color: rgba(255, 201, 60, 0.85);
  color: #ffe08a;
}
#touch .touch-nitro {
  grid-area: nitro;
  border-color: rgba(77, 255, 176, 0.85);
  color: #c4ffe6;
}
#touch .touch-cam {
  grid-area: cam;
  border-color: rgba(106, 142, 200, 0.8);
  color: #cfe0ff;
  min-height: 40px;
}
#touch .touch-btn.is-active,
#touch .touch-steer.is-active {
  background: rgba(255, 61, 154, 0.35);
  box-shadow: 0 0 18px rgba(255, 61, 154, 0.35);
}
#touch .touch-brake.is-active {
  background: rgba(255, 90, 90, 0.4);
}
#touch .touch-fire.is-active {
  background: rgba(255, 201, 60, 0.35);
}
#touch .touch-nitro.is-active {
  background: rgba(77, 255, 176, 0.3);
}
#touch .touch-boost.is-active {
  background: rgba(255, 61, 139, 0.4);
}

@media (orientation: landscape) and (max-height: 480px) {
  #touch .touch-steer {
    width: min(28vw, 118px);
    height: min(28vw, 118px);
  }
  #touch .touch-air {
    bottom: calc(max(8px, env(safe-area-inset-bottom)) + min(28vw, 118px) + 6px);
  }
  #touch .touch-air-btn {
    width: 48px;
    height: 34px;
    min-height: 34px;
  }
  #touch .touch-actions {
    grid-template-columns: repeat(2, minmax(56px, 14vw));
    gap: 5px;
  }
  #touch .touch-btn { min-height: 40px; font-size: 10px; }
  #touch .touch-brake { min-height: 44px; }
  #touch .touch-cam { min-height: 34px; }
}

@media (orientation: portrait) {
  #touch .touch-steer {
    width: min(40vw, 156px);
    height: min(40vw, 156px);
  }
  #touch .touch-air {
    bottom: calc(max(12px, env(safe-area-inset-bottom)) + min(40vw, 156px) + 8px);
  }
  #touch .touch-actions {
    grid-template-columns: repeat(2, minmax(70px, 20vw));
  }
}

@media (max-height: 420px) {
  #touch .touch-label { display: none; }
  #touch .touch-steer {
    width: min(26vw, 104px);
    height: min(26vw, 104px);
  }
  #touch .touch-air {
    bottom: calc(max(6px, env(safe-area-inset-bottom)) + min(26vw, 104px) + 4px);
  }
  #touch .touch-btn { min-height: 36px; font-size: 9px; border-radius: 8px; }
  #touch .touch-brake { min-height: 40px; }
}
`;

let injected = false;
export function injectTouchStyles() {
  if (injected || typeof document === 'undefined') return;
  injected = true;
  const style = document.createElement('style');
  style.id = 'touch-controls-css';
  style.textContent = css;
  document.head.appendChild(style);
}
