/**
 * Missile lock-on + drift-break escape.
 *
 * Improvements over the first pass:
 *   · sticky current target (hysteresis + score bonus)
 *   · soft acquire vs maintain cones
 *   · acquire rate scales with how centred / close the paint is
 *   · short lead prediction so crossing craft stay lockable
 *   · retarget only when a rival clearly beats the current paint
 *
 * Tunables live in `core/combatTune.ts`.
 */

import { COMBAT } from '../core/combatTune';
import type { Racer } from '../core/types';

export const LOCK_RANGE_MIN = COMBAT.lock.rangeMin;
export const LOCK_RANGE_MAX = COMBAT.lock.rangeMax;
/** @deprecated use COMBAT.lock.coneAcquire — kept for call sites. */
export const LOCK_CONE = COMBAT.lock.coneAcquire;
export const LOCK_ACQUIRE_SEC = COMBAT.lock.acquireSec;
export const HIT_CHANCE_MIN = COMBAT.lock.hitChanceMin;
export const HIT_CHANCE_MAX = COMBAT.lock.hitChanceMax;
export const LOCK_FIRE_GATE = COMBAT.lock.fireGate;
export const LOCK_GUIDED_MIN = COMBAT.lock.guidedMin;
export const LOCK_IMMUNE_SEC = COMBAT.lock.immuneSec;
export const ROCKET_MAX_AMMO = COMBAT.rocket.maxAmmo;

export type LockState = {
  targetId: number | null;
  /** 0…1 acquire strength. */
  strength: number;
};

export type BreakState = {
  /** 0…1 break charge while painted / under threat. */
  meter: number;
  /** Seconds of lock immunity after a break. */
  immune: number;
  /** Flash cue for HUD. */
  breakFlash: number;
};

export function createLockState(): LockState {
  return { targetId: null, strength: 0 };
}

export function createBreakState(): BreakState {
  return { meter: 0, immune: 0, breakFlash: 0 };
}

export function hitChanceFromLock(strength: number): number {
  const t = Math.max(0, Math.min(1, strength));
  const shaped = Math.pow(t, 1.15);
  return HIT_CHANCE_MIN + shaped * (HIT_CHANCE_MAX - HIT_CHANCE_MIN);
}

function forward(heading: number): { x: number; z: number } {
  return { x: Math.sin(heading), z: Math.cos(heading) };
}

function clamp01(v: number) {
  return Math.max(0, Math.min(1, v));
}

/** Dual airbrake slide — WaveSpace stand-in for WaveKill drift. */
export function isDrifting(r: Racer): boolean {
  const c = r.controls;
  const s = r.state;
  const dual = c.airbrakeL && c.airbrakeR;
  const slip = Math.abs(s.lateralSpeed);
  return dual && (slip > 3.5 || s.appliedThrottle < 0.5 || c.brake > 0.35);
}

/**
 * Real dodge slide that can spoil an inbound rocket.
 * AI panic dual-brake (low throttle + brake, little slip) must NOT count —
 * otherwise locking a rival auto-softens every guided shot.
 */
export function isDodgeDrifting(r: Racer): boolean {
  return isDrifting(r) && Math.abs(r.state.lateralSpeed) > 8.5;
}

export type LockScore = {
  score: number;
  /** 0…1 how clean the paint is (centred + close). */
  quality: number;
  dist: number;
  dot: number;
};

/**
 * Score a candidate. `maintain` uses the wider outer cone so an existing
 * paint doesn't drop from a brief edge wobble.
 */
export function scoreLockTarget(
  shooter: Racer,
  target: Racer,
  immune: number,
  maintain = false,
): LockScore {
  const bad: LockScore = { score: -1, quality: 0, dist: 0, dot: 0 };
  if (target.id === shooter.id) return bad;
  if (target.destroyed || target.state.hp <= 0) return bad;
  if (immune > 0) return bad;

  const L = COMBAT.lock;
  const lead = L.leadSec;
  const dx =
    target.state.position.x + target.state.velocity.x * lead - shooter.state.position.x;
  const dz =
    target.state.position.z + target.state.velocity.z * lead - shooter.state.position.z;
  const dist = Math.hypot(dx, dz);
  if (dist < L.rangeMin || dist > L.rangeMax) return bad;

  const f = forward(shooter.state.heading);
  const dot = (f.x * dx + f.z * dz) / dist;
  const cone = maintain ? L.coneMaintain : L.coneAcquire;
  if (dot < cone) return bad;

  // Quality: centred in acquire cone + nearer. Used to scale acquire rate.
  const coneSpan = Math.max(1e-3, 1 - L.coneAcquire);
  const centre = clamp01((dot - L.coneAcquire) / coneSpan);
  const near = clamp01(1 - (dist - L.rangeMin) / (L.rangeMax - L.rangeMin));
  const quality = centre * 0.55 + near * 0.45;

  // Prefer centreline paint, then closer, slight aspect (tail-on easier).
  const tf = forward(target.state.heading);
  const closing = -(tf.x * f.x + tf.z * f.z); // +1 = target heading toward us
  const aspect = clamp01(0.5 + closing * 0.35);
  const score = dot * 1.45 + near * 1.25 + centre * 0.85 + aspect * 0.35;

  return { score, quality, dist, dot };
}

/**
 * Tactical hunt weight for AI shooters — place rivals, wounded craft, and
 * clean ahead shots beat random pack spray. Player is a rival, not the only one.
 */
export function aiHuntBonus(shooter: Racer, target: Racer): number {
  if (shooter.isPlayer) return 0;
  let bonus = 0;

  const placeDelta = (target.place ?? 99) - (shooter.place ?? 99);
  // Lower place number = ahead. Hunt the craft blocking you.
  if (placeDelta < 0) bonus += 0.55;
  else if (placeDelta <= 2) bonus += 0.32;

  const dProg = target.progress - shooter.progress;
  if (dProg > 0.01 && dProg < 0.4) bonus += 0.48;
  else if (dProg > -0.1 && dProg <= 0.01) bonus += 0.22;

  const hpFrac = target.hull.hp / Math.max(1, target.hull.maxHp);
  if (hpFrac < 0.4) bonus += 0.6;
  else if (hpFrac < 0.65) bonus += 0.28;

  if (target.isPlayer) bonus += 0.38;

  const p = shooter.personality;
  if (p === 'aggressive') {
    if (target.isPlayer) bonus += 0.32;
    if (placeDelta < 0) bonus += 0.28;
    if (hpFrac < 0.5) bonus += 0.18;
  } else if (p === 'clean') {
    // Patient: clear ahead paint and wounded finishers.
    if (dProg > 0.02 && dProg < 0.28) bonus += 0.4;
    if (hpFrac < 0.45) bonus += 0.25;
  } else if (p === 'erratic') {
    bonus += ((target.id * 17) % 5) * 0.08 + (target.id % 2 === 0 ? 0.2 : -0.05);
  }

  // Stacked ammo: bias the last round toward place threats / wounded.
  if (shooter.state.weaponAmmo <= 1 && COMBAT.rocket.maxAmmo > 1) {
    if (placeDelta < 0 || hpFrac < 0.45 || target.isPlayer) bonus += 0.35;
    else bonus -= 0.25;
  }

  return bonus;
}

export function pickLockTarget(
  shooter: Racer,
  racers: Racer[],
  immuneOf: (id: number) => number,
  currentId: number | null,
): { target: Racer; quality: number } | null {
  const L = COMBAT.lock;
  let best: Racer | null = null;
  let bestScore = -1;
  let bestQuality = 0;
  let current: Racer | null = null;
  let currentScore = -1;
  let currentQuality = 0;

  for (const t of racers) {
    const isCurrent = currentId != null && t.id === currentId;
    const s = scoreLockTarget(shooter, t, immuneOf(t.id), isCurrent);
    if (s.score < 0) continue;
    const sticky = isCurrent ? L.stickyBonus : 0;
    const scored = s.score + sticky + aiHuntBonus(shooter, t);
    if (isCurrent) {
      current = t;
      currentScore = scored;
      currentQuality = s.quality;
    }
    if (scored > bestScore) {
      bestScore = scored;
      best = t;
      bestQuality = s.quality;
    }
  }

  if (!best) return null;

  // Hysteresis: keep current unless a rival clearly wins.
  if (current && best.id !== current.id) {
    if (bestScore < currentScore + L.switchMargin) {
      return { target: current, quality: currentQuality };
    }
  }
  return { target: best, quality: bestQuality };
}

/** Advance auto-lock for one shooter. */
export function tickLock(
  lock: LockState,
  shooter: Racer,
  racers: Racer[],
  dt: number,
  immuneOf: (id: number) => number,
): void {
  const L = COMBAT.lock;
  if (shooter.destroyed || shooter.state.hp <= 0) {
    lock.targetId = null;
    lock.strength = 0;
    return;
  }
  // No rocket in the rack — never paint enemies (HUD / beacons / threat).
  if (shooter.state.weapon !== 'missile' || shooter.state.weaponAmmo <= 0) {
    lock.targetId = null;
    lock.strength = 0;
    return;
  }

  const picked = pickLockTarget(shooter, racers, immuneOf, lock.targetId);

  if (!picked) {
    // Soft drop — brief cone exits don't hard-reset.
    lock.strength = Math.max(0, lock.strength - dt * L.loseEmptyRate);
    if (lock.strength <= 0.02) {
      lock.targetId = null;
      lock.strength = 0;
    }
    return;
  }

  const { target, quality } = picked;

  if (lock.targetId === target.id) {
    // Faster acquire when the paint is clean; crawl at the edge.
    const rate = L.acquireEdgeMul + (1 - L.acquireEdgeMul) * quality;
    lock.strength = Math.min(1, lock.strength + (dt / L.acquireSec) * rate);
    return;
  }

  // Retarget — keep a scrap of progress so swaps don't feel binary.
  const keep = Math.min(0.4, lock.strength * 0.45 + 0.06 + quality * 0.12);
  lock.targetId = target.id;
  lock.strength = keep;
}

/**
 * Drift-break while painted or under inbound rocket threat.
 * Returns true on the frame locks shatter / rockets spoil.
 */
export function tickDriftBreak(
  brk: BreakState,
  target: Racer,
  threatened: boolean,
  dt: number,
): boolean {
  brk.immune = Math.max(0, brk.immune - dt);
  brk.breakFlash = Math.max(0, brk.breakFlash - dt);

  if (!threatened || target.destroyed || target.state.hp <= 0) {
    brk.meter = Math.max(0, brk.meter - dt * 0.7);
    return false;
  }

  const s = target.state;
  const c = target.controls;
  const slip = Math.abs(s.lateralSpeed);
  const dualAir = c.airbrakeL && c.airbrakeR;

  // Only a real high-slip dodge charges the break. AI panic dual-brake
  // (low throttle + brake, little slip) must not auto-shatter every lock.
  if (isDodgeDrifting(target)) {
    const rate =
      0.9 +
      slip * 0.05 +
      (slip > 12 ? 0.35 : 0) +
      (dualAir ? 0.2 : 0) +
      (c.brake > 0.4 ? 0.15 : 0);
    brk.meter += dt * rate;
  } else {
    brk.meter = Math.max(0, brk.meter - dt * 0.5);
  }

  if (brk.meter >= 1) {
    brk.meter = 0;
    brk.immune = LOCK_IMMUNE_SEC;
    brk.breakFlash = 1.45;
    return true;
  }
  return false;
}

/** @deprecated alias — older call sites */
export const tickAirbrakeBreak = tickDriftBreak;
