/**
 * AG interceptor — slim fuselage, swept wings, twin stern thrusters, bubble
 * canopy. Faceted for the cel pipeline (not a filled triangle wedge).
 *
 * Seat/grip anchors are fixed; do not move SEAT_LOCAL / GRIP_LOCAL without
 * updating the rider IK. Trail FX expects thrusters ≈ (±0.85, 0.16, -3.0).
 */

import { BufferAttribute, BufferGeometry, Color, Group, Mesh, Object3D, Vector3 } from 'three';
import { PAL, RACER_COLORS } from '../core/palette';
import { applyCel, createCelMaterial, type CelMaterialSet } from '../render/celMaterial';

// ─────────────────────────────────────────────────────────────────────────────
// Triangle soup builder
// ─────────────────────────────────────────────────────────────────────────────

type V3 = readonly [number, number, number];
/** 2D cross-section point, (x, y). */
type P2 = readonly [number, number];
/** Corner rect for a tapered box: [x0, x1, y0, y1]. */
type Rect = readonly [number, number, number, number];

const mirrorX = (v: V3): V3 => [-v[0], v[1], v[2]];

let facetCounter = 0;

class Surface {
  private p: number[] = [];
  private f: number[] = [];
  private facet = 0;

  beginFacet() {
    this.facet = ++facetCounter;
    return this;
  }

  endFacet() {
    this.facet = 0;
  }

  tri(a: V3, b: V3, c: V3) {
    this.p.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]);
    this.f.push(this.facet);
  }

  quad(a: V3, b: V3, c: V3, d: V3) {
    this.tri(a, b, c);
    this.tri(a, c, d);
  }

  quadMirrored(sign: number, a: V3, b: V3, c: V3, d: V3) {
    if (sign > 0) this.quad(a, b, c, d);
    else this.quad(mirrorX(a), mirrorX(d), mirrorX(c), mirrorX(b));
  }

  loft(ringA: V3[], ringB: V3[], flip = false, from = 0, to = -1) {
    const end = to < 0 ? ringA.length - 1 : to;
    for (let j = from; j < end; j++) {
      if (flip) this.quad(ringA[j], ringB[j], ringB[j + 1], ringA[j + 1]);
      else this.quad(ringA[j], ringA[j + 1], ringB[j + 1], ringB[j]);
    }
  }

  cap(ring: V3[], centre: V3, want: V3, closed = true) {
    const n = ring.length;
    const probe = triNormal(centre, ring[0], ring[1]);
    const flip = probe[0] * want[0] + probe[1] * want[1] + probe[2] * want[2] < 0;
    const last = closed ? n : n - 1;
    for (let j = 0; j < last; j++) {
      const a = ring[j];
      const b = ring[(j + 1) % n];
      if (flip) this.tri(centre, b, a);
      else this.tri(centre, a, b);
    }
  }

  box(x0: number, x1: number, y0: number, y1: number, z0: number, z1: number) {
    this.taperBox(z0, z1, [x0, x1, y0, y1], [x0, x1, y0, y1]);
  }

  taperBox(
    z0: number,
    z1: number,
    rect0: Rect,
    rect1: Rect,
    capBack = true,
    capFront = true,
    skipTop = false,
  ) {
    if (z0 > z1) {
      const t = z0; z0 = z1; z1 = t;
      const rt = rect0; rect0 = rect1; rect1 = rt;
    }
    const r0 = sortRect(rect0);
    const r1 = sortRect(rect1);
    const A0: V3 = [r0[0], r0[2], z0], B0: V3 = [r0[1], r0[2], z0];
    const C0: V3 = [r0[1], r0[3], z0], D0: V3 = [r0[0], r0[3], z0];
    const A1: V3 = [r1[0], r1[2], z1], B1: V3 = [r1[1], r1[2], z1];
    const C1: V3 = [r1[1], r1[3], z1], D1: V3 = [r1[0], r1[3], z1];
    this.quad(B0, C0, C1, B1);
    this.quad(A1, D1, D0, A0);
    if (!skipTop) this.quad(D0, D1, C1, C0);
    this.quad(A1, A0, B0, B1);
    if (capFront) this.quad(A1, B1, C1, D1);
    if (capBack) this.quad(B0, A0, D0, C0);
  }

  prism(profile: P2[], z0: number, z1: number, capBack = true, capFront = true) {
    const n = profile.length;
    for (let j = 0; j < n; j++) {
      const p = profile[j];
      const q = profile[(j + 1) % n];
      this.quad([p[0], p[1], z0], [q[0], q[1], z0], [q[0], q[1], z1], [p[0], p[1], z1]);
    }
    const cx = profile.reduce((s, p) => s + p[0], 0) / n;
    const cy = profile.reduce((s, p) => s + p[1], 0) / n;
    const ring0 = profile.map((p): V3 => [p[0], p[1], z0]);
    const ring1 = profile.map((p): V3 => [p[0], p[1], z1]);
    if (capBack) this.cap(ring0, [cx, cy, z0], [0, 0, -1]);
    if (capFront) this.cap(ring1, [cx, cy, z1], [0, 0, 1]);
  }

  append(other: Surface) {
    for (let i = 0; i < other.p.length; i++) this.p.push(other.p[i]);
    for (let i = 0; i < other.f.length; i++) this.f.push(other.f[i]);
  }

  get triangleCount() {
    return this.p.length / 9;
  }

  geometry(name: string): BufferGeometry {
    const count = this.p.length / 3;
    const tris = count / 3;
    const pos = new Float32Array(this.p);
    const nrm = new Float32Array(count * 3);
    const uv = new Float32Array(count * 2);

    const fx = new Float64Array(tris);
    const fy = new Float64Array(tris);
    const fz = new Float64Array(tris);
    for (let t = 0; t < tris; t++) {
      const o = t * 9;
      const ux = pos[o + 3] - pos[o], uy = pos[o + 4] - pos[o + 1], uz = pos[o + 5] - pos[o + 2];
      const vx = pos[o + 6] - pos[o], vy = pos[o + 7] - pos[o + 1], vz = pos[o + 8] - pos[o + 2];
      fx[t] = uy * vz - uz * vy;
      fy[t] = uz * vx - ux * vz;
      fz[t] = ux * vy - uy * vx;
    }

    const acc = new Map<number, [number, number, number]>();
    for (let t = 0; t < tris; t++) {
      const id = this.f[t] ?? 0;
      if (id === 0) continue;
      const a = acc.get(id);
      if (a) {
        a[0] += fx[t];
        a[1] += fy[t];
        a[2] += fz[t];
      } else acc.set(id, [fx[t], fy[t], fz[t]]);
    }

    for (let t = 0; t < tris; t++) {
      const id = this.f[t] ?? 0;
      let nx = fx[t], ny = fy[t], nz = fz[t];
      if (id !== 0) {
        const a = acc.get(id)!;
        if (Math.hypot(a[0], a[1], a[2]) > 1e-9) {
          nx = a[0];
          ny = a[1];
          nz = a[2];
        }
      }
      const len = Math.hypot(nx, ny, nz) || 1;
      nx /= len;
      ny /= len;
      nz /= len;
      const o = t * 9;
      for (let k = 0; k < 3; k++) {
        nrm[o + k * 3 + 0] = nx;
        nrm[o + k * 3 + 1] = ny;
        nrm[o + k * 3 + 2] = nz;
      }
    }
    for (let i = 0; i < count; i++) {
      uv[i * 2 + 0] = pos[i * 3 + 0] * 0.5 + 0.5;
      uv[i * 2 + 1] = pos[i * 3 + 2] * 0.2 + 0.5;
    }
    const g = new BufferGeometry();
    g.name = name;
    g.setAttribute('position', new BufferAttribute(pos, 3));
    g.setAttribute('normal', new BufferAttribute(nrm, 3));
    g.setAttribute('uv', new BufferAttribute(uv, 2));
    g.computeBoundingSphere();
    return g;
  }
}

function sortRect(r: Rect): Rect {
  return [Math.min(r[0], r[1]), Math.max(r[0], r[1]), Math.min(r[2], r[3]), Math.max(r[2], r[3])];
}

function triNormal(a: V3, b: V3, c: V3): V3 {
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2];
  const vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
  const nx = uy * vz - uz * vy;
  const ny = uz * vx - ux * vz;
  const nz = ux * vy - uy * vx;
  const len = Math.hypot(nx, ny, nz) || 1;
  return [nx / len, ny / len, nz / len];
}

// ─────────────────────────────────────────────────────────────────────────────
// Seat / grip contract (rider parents here)
// ─────────────────────────────────────────────────────────────────────────────

/** Hips origin in craft-local space — mid cockpit. */
export const SEAT_LOCAL = new Vector3(0, 0.52, -0.18);
/** Yoke grip centre. */
export const GRIP_LOCAL = new Vector3(0, 0.68, 0.42);
export const GRIP_HALF_WIDTH = 0.28;

export interface ShipMesh {
  group: Group;
  seat: Object3D;
  grip: Object3D;
  materials: CelMaterialSet[];
  triangles: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Cel materials
// ─────────────────────────────────────────────────────────────────────────────

/** World scale applied in `createRacer` — keep trails in sync. */
export const SHIP_MESH_SCALE = 1.18;
/** Mesh group Y bias so the AG belly clears the origin. */
export const SHIP_MESH_Y = 0.1;

function normalisedHue(c: Color): Color {
  const m = Math.max(c.r, c.g, c.b) || 1;
  return c.clone().multiplyScalar(1 / m);
}
const NEUTRAL = normalisedHue(PAL.hudPaper);
const COOL = normalisedHue(PAL.skyMid).lerp(NEUTRAL, 0.55);
const WARM = normalisedHue(PAL.sun).lerp(NEUTRAL, 0.7);

/** Team-tinted cel ladder — shadow keeps hue, highlight blooms toward sun. */
function paintRamp(hull: Color): Color[] {
  const shadow = hull.clone().multiplyScalar(0.32).lerp(COOL.clone().multiplyScalar(0.22), 0.28);
  const mid = hull.clone().multiplyScalar(0.7);
  const lit = hull.clone().lerp(WARM, 0.18).multiplyScalar(1.08);
  const hot = hull.clone().lerp(PAL.sunCore, 0.42).multiplyScalar(1.22);
  return [shadow, mid, lit, hot];
}

function accentRamp(hull: Color): Color[] {
  const base = hull.clone().lerp(PAL.foam, 0.72);
  return [
    base.clone().multiplyScalar(0.55),
    base.clone().multiplyScalar(0.85),
    base.clone().lerp(PAL.foam, 0.35).multiplyScalar(1.05),
    PAL.foam.clone().lerp(hull, 0.08).multiplyScalar(1.12),
  ];
}

const PAINT_STOPS = [0.0, 0.36, 0.54, 0.8];

function makeMaterials(id: number) {
  const colourId = ((id % RACER_COLORS.length) + RACER_COLORS.length) % RACER_COLORS.length;
  const hullColor = RACER_COLORS[colourId]!.hull;
  const accent = hullColor.clone().lerp(PAL.boostHot, 0.2);

  const hull = createCelMaterial({
    name: `hull${id}`,
    color: hullColor,
    rampColors: paintRamp(hullColor),
    rampStops: PAINT_STOPS,
    specSize: 0.968,
    specSize2: 0.99,
    specStrength: 0.28,
    rimColor: accent,
    rimPower: 2.4,
    rimStrength: 1.05,
    outlineWidthPx: 4.8,
    ambientStrength: 0.92,
  });
  // Dark carbon trim — cool ink with a whisper of team hue in the lit band.
  const trim = createCelMaterial({
    name: `trim${id}`,
    color: PAL.inkSoft.clone().lerp(hullColor, 0.12),
    rampColors: [
      PAL.ink.clone().multiplyScalar(1.1),
      PAL.inkSoft.clone().lerp(hullColor, 0.08),
      COOL.clone().multiplyScalar(2.4).lerp(hullColor, 0.15),
      WARM.clone().multiplyScalar(3.8).lerp(accent, 0.2),
    ],
    rampStops: PAINT_STOPS,
    specSize: 0.955,
    specSize2: 0.988,
    specStrength: 0.45,
    rimColor: accent,
    rimPower: 2.2,
    rimStrength: 0.85,
    outlineWidthPx: 3.2,
    ambientStrength: 0.9,
  });
  // Racing stripe / edge lip — white with team tint so packs stay readable.
  const bright = createCelMaterial({
    name: `bright${id}`,
    color: PAL.foam.clone().lerp(hullColor, 0.14),
    rampColors: accentRamp(hullColor),
    rampStops: PAINT_STOPS,
    specSize: 0.965,
    specSize2: 0.99,
    specStrength: 0.22,
    rimColor: accent,
    rimPower: 2.2,
    rimStrength: 0.75,
    outlineWidthPx: 3.2,
    ambientStrength: 1.15,
  });
  const glass = createCelMaterial({
    name: `glass${id}`,
    color: PAL.skyHorizon.clone().lerp(hullColor, 0.18),
    rampColors: [
      COOL.clone().multiplyScalar(0.5).lerp(hullColor, 0.2),
      PAL.waterShallow.clone().lerp(hullColor, 0.15),
      PAL.foam.clone().multiplyScalar(0.95),
    ],
    rampStops: [0.0, 0.38, 0.72],
    specSize: 0.93,
    specSize2: 0.982,
    specStrength: 0.62,
    rimColor: PAL.foam,
    rimPower: 1.6,
    rimStrength: 1.15,
    outlineWidthPx: 3.2,
    glassBands: 1.4,
    ambientStrength: 1.05,
  });
  // Thruster throat — magenta core with team-coloured outer bloom.
  const glow = createCelMaterial({
    name: `glow${id}`,
    color: PAL.boostHot.clone().lerp(accent, 0.25),
    rampColors: [
      hullColor.clone().multiplyScalar(0.45).lerp(PAL.boost, 0.55),
      PAL.boost.clone().lerp(hullColor, 0.2),
      PAL.boostHot,
      PAL.sunCore,
    ],
    rampStops: [0.0, 0.22, 0.52, 0.82],
    specSize: 0.86,
    specSize2: 0.95,
    specStrength: 0.72,
    rimColor: PAL.boostHot,
    rimPower: 1.3,
    rimStrength: 1.35,
    outlineWidthPx: 2.0,
    ambientStrength: 1.45,
  });
  return { hull, trim, bright, glass, glow };
}

// ─────────────────────────────────────────────────────────────────────────────
// AG interceptor — fuselage + wings (not a filled triangle)
// ─────────────────────────────────────────────────────────────────────────────
//
// Top-down read:
//
//              nose
//               ║
//           ─═══╬═══─   canards
//              /║\
//         ════╡ ╟ ╞════  main wings
//              ║║
//             ●  ●       twin thrusters
//
// Volume lives in a slim fuselage; lift surfaces are thin wings so the craft
// reads as a vehicle, not a flat arrowhead plate.

type Station = {
  z: number;
  /** Fuselage half-width at the chine (body only — wings are separate). */
  half: number;
  deck: number;
  chine: number;
  belly: number;
};

/** Stern → nose body stations — oval tube, not a triangle planform. */
const STATIONS: readonly Station[] = [
  { z: -2.35, half: 0.42, deck: 0.46, chine: 0.18, belly: -0.14 },
  { z: -1.55, half: 0.48, deck: 0.5, chine: 0.2, belly: -0.16 },
  { z: -0.7, half: 0.52, deck: 0.54, chine: 0.22, belly: -0.14 },
  { z: 0.15, half: 0.5, deck: 0.52, chine: 0.22, belly: -0.12 },
  { z: 1.0, half: 0.42, deck: 0.48, chine: 0.2, belly: -0.08 },
  { z: 1.85, half: 0.3, deck: 0.4, chine: 0.18, belly: -0.02 },
  { z: 2.55, half: 0.16, deck: 0.32, chine: 0.16, belly: 0.06 },
  { z: 3.05, half: 0.04, deck: 0.24, chine: 0.16, belly: 0.12 },
];

/**
 * Rounded fuselage ring: port chine → crown → starboard → keel → close.
 * More mid-side points than the old wedge so the body reads as a tube.
 */
function hullRing(st: Station): V3[] {
  const w = st.half;
  const z = st.z;
  const d = st.deck;
  const c = st.chine;
  const b = st.belly;
  return [
    [-w, c, z],
    [-w * 0.92, d * 0.55 + c * 0.45, z],
    [-w * 0.72, d, z],
    [-w * 0.28, d + 0.04, z],
    [0, d + 0.06, z],
    [w * 0.28, d + 0.04, z],
    [w * 0.72, d, z],
    [w * 0.92, d * 0.55 + c * 0.45, z],
    [w, c, z],
    [w * 0.78, (c + b) * 0.45, z],
    [w * 0.4, b + 0.02, z],
    [0, b - 0.04, z],
    [-w * 0.4, b + 0.02, z],
    [-w * 0.78, (c + b) * 0.45, z],
    [-w, c, z],
  ];
}

function loftHull(surf: Surface, stations: readonly Station[], capStern = true) {
  const rings = stations.map(hullRing);
  const segs = rings[0]!.length - 1;
  for (let j = 0; j < segs; j++) {
    surf.beginFacet();
    for (let i = 0; i < rings.length - 1; i++) {
      const a = rings[i]!;
      const b = rings[i + 1]!;
      surf.quad(a[j], a[j + 1], b[j + 1], b[j]);
    }
    surf.endFacet();
  }
  if (capStern) {
    const stern = rings[0]!;
    surf.beginFacet();
    surf.cap(
      stern.slice(0, -1),
      [0, (stern[4][1] + stern[11][1]) * 0.5, stern[0][2]],
      [0, 0, -1],
      true,
    );
    surf.endFacet();
  }
}

/** Thin airfoil chord section in the XZ plane, extruded along local span. */
function wingPanel(
  surf: Surface,
  sign: number,
  rootX: number,
  tipX: number,
  zLeRoot: number,
  zTeRoot: number,
  zLeTip: number,
  zTeTip: number,
  y: number,
  thick: number,
) {
  const y0 = y - thick * 0.5;
  const y1 = y + thick * 0.5;
  // Upper + lower skins
  for (const yy of [y0, y1] as const) {
    surf.beginFacet();
    surf.quadMirrored(
      sign,
      [rootX, yy, zTeRoot],
      [rootX, yy, zLeRoot],
      [tipX, yy, zLeTip],
      [tipX, yy, zTeTip],
    );
    surf.endFacet();
  }
  // Leading / trailing edges + tip cap
  surf.beginFacet();
  surf.quadMirrored(
    sign,
    [rootX, y0, zLeRoot],
    [rootX, y1, zLeRoot],
    [tipX, y1, zLeTip],
    [tipX, y0, zLeTip],
  );
  surf.quadMirrored(
    sign,
    [rootX, y1, zTeRoot],
    [rootX, y0, zTeRoot],
    [tipX, y0, zTeTip],
    [tipX, y1, zTeTip],
  );
  surf.quadMirrored(
    sign,
    [tipX, y0, zTeTip],
    [tipX, y0, zLeTip],
    [tipX, y1, zLeTip],
    [tipX, y1, zTeTip],
  );
  surf.endFacet();
}

export function createShipMesh(id: number): ShipMesh {
  const HULL = new Surface();
  const TRIM = new Surface();
  const BRIGHT = new Surface();
  const GLASS = new Surface();
  const GLOW = new Surface();

  // ── Fuselage tube ─────────────────────────────────────────────────────────
  loftHull(HULL, STATIONS);

  // Inner AG belly fairing (darker, slightly inset)
  const bellyStations = STATIONS.map((st) => ({
    ...st,
    half: st.half * 0.78,
    deck: st.chine + 0.04,
    chine: (st.chine + st.belly) * 0.55,
    belly: st.belly - 0.05,
  }));
  loftHull(TRIM, bellyStations, false);

  // Centre racing stripe along the spine
  BRIGHT.beginFacet();
  BRIGHT.taperBox(-2.1, 2.7, [-0.07, 0.07, 0.5, 0.56], [-0.02, 0.02, 0.28, 0.32]);
  BRIGHT.endFacet();
  TRIM.taperBox(-2.05, 2.65, [-0.085, -0.065, 0.505, 0.555], [-0.028, -0.016, 0.285, 0.315]);
  TRIM.taperBox(-2.05, 2.65, [0.065, 0.085, 0.505, 0.555], [0.016, 0.028, 0.285, 0.315]);

  // Nose cone + sensor tip
  {
    HULL.beginFacet();
    const tip: V3 = [0, 0.2, 3.28];
    const base: V3[] = [
      [-0.1, 0.12, 2.95],
      [0.1, 0.12, 2.95],
      [0.08, 0.28, 2.95],
      [-0.08, 0.28, 2.95],
    ];
    HULL.tri(tip, base[0], base[1]);
    HULL.tri(tip, base[1], base[2]);
    HULL.tri(tip, base[2], base[3]);
    HULL.tri(tip, base[3], base[0]);
    HULL.endFacet();
    TRIM.taperBox(3.05, 3.32, [-0.03, 0.03, 0.16, 0.24], [-0.01, 0.01, 0.19, 0.22]);
    BRIGHT.taperBox(2.85, 3.1, [-0.07, 0.07, 0.26, 0.34], [-0.025, 0.025, 0.2, 0.26]);
    GLOW.taperBox(3.18, 3.34, [-0.02, 0.02, 0.18, 0.22], [-0.008, 0.008, 0.19, 0.21]);
  }

  // ── Forward canards ───────────────────────────────────────────────────────
  for (const sign of [-1, 1] as const) {
    wingPanel(HULL, sign, 0.18, 0.72, 2.55, 2.15, 2.75, 2.45, 0.2, 0.05);
    wingPanel(BRIGHT, sign, 0.2, 0.68, 2.52, 2.2, 2.7, 2.48, 0.225, 0.02);
    TRIM.taperBox(2.2, 2.55, [sign * 0.16, sign * 0.28, 0.16, 0.26], [sign * 0.55, sign * 0.7, 0.17, 0.24]);
  }

  // ── Main swept wings ──────────────────────────────────────────────────────
  for (const sign of [-1, 1] as const) {
    // Primary wing plane — long chord at root, swept tip
    wingPanel(HULL, sign, 0.42, 1.85, 0.85, -1.35, 0.15, -0.55, 0.22, 0.07);
    // Underside bevel lip for cel edge
    wingPanel(TRIM, sign, 0.45, 1.78, 0.75, -1.25, 0.1, -0.5, 0.17, 0.03);
    // Leading-edge bright strip
    BRIGHT.beginFacet();
    BRIGHT.quadMirrored(
      sign,
      [0.45, 0.255, 0.82],
      [0.45, 0.255, 0.72],
      [1.8, 0.255, 0.05],
      [1.8, 0.255, 0.18],
    );
    BRIGHT.endFacet();
    // Wing fence / tip plate
    HULL.beginFacet();
    HULL.quadMirrored(
      sign,
      [1.78, 0.12, -0.52],
      [1.92, 0.12, -0.48],
      [1.92, 0.34, -0.48],
      [1.78, 0.34, -0.52],
    );
    HULL.quadMirrored(
      sign,
      [1.78, 0.14, 0.08],
      [1.9, 0.14, 0.05],
      [1.9, 0.32, 0.05],
      [1.78, 0.32, 0.08],
    );
    HULL.endFacet();
    GLOW.taperBox(-0.55, -0.35, [sign * 1.82, sign * 1.96, 0.2, 0.3], [sign * 1.78, sign * 1.9, 0.22, 0.32]);
    // Control surface hash on trailing edge
    for (let k = 0; k < 3; k++) {
      const x0 = 0.7 + k * 0.32;
      BRIGHT.box(sign * x0, sign * (x0 + 0.18), 0.24, 0.27, -1.15 + k * 0.12, -1.05 + k * 0.12);
    }
  }

  // Wing root fairings into the fuselage
  for (const sign of [-1, 1] as const) {
    HULL.beginFacet();
    HULL.taperBox(-1.2, 0.7, [sign * 0.38, sign * 0.62, 0.12, 0.36], [sign * 0.36, sign * 0.55, 0.16, 0.38]);
    HULL.endFacet();
    TRIM.taperBox(-0.4, 0.55, [sign * 0.48, sign * 0.7, 0.28, 0.42], [sign * 0.45, sign * 0.62, 0.3, 0.44]);
  }

  // ── Shoulder intakes ──────────────────────────────────────────────────────
  for (const sign of [-1, 1] as const) {
    TRIM.beginFacet();
    TRIM.taperBox(0.35, 1.15, [sign * 0.28, sign * 0.55, 0.3, 0.52], [sign * 0.22, sign * 0.42, 0.32, 0.5]);
    TRIM.endFacet();
    GLOW.taperBox(0.95, 1.12, [sign * 0.32, sign * 0.48, 0.36, 0.48], [sign * 0.3, sign * 0.45, 0.38, 0.46]);
    BRIGHT.taperBox(1.05, 1.18, [sign * 0.3, sign * 0.46, 0.48, 0.54], [sign * 0.28, sign * 0.42, 0.46, 0.52]);
    // Scoop lip
    HULL.taperBox(1.05, 1.25, [sign * 0.25, sign * 0.5, 0.42, 0.56], [sign * 0.22, sign * 0.4, 0.4, 0.52]);
  }

  // ── Ventral AG pads ───────────────────────────────────────────────────────
  GLOW.beginFacet();
  GLOW.taperBox(-1.6, 1.1, [-0.32, 0.32, -0.2, -0.14], [-0.16, 0.16, -0.14, -0.1]);
  GLOW.endFacet();
  for (const sign of [-1, 1] as const) {
    GLOW.taperBox(-1.9, -0.2, [sign * 0.2, sign * 0.55, -0.18, -0.12], [sign * 0.15, sign * 0.4, -0.14, -0.1]);
    GLOW.taperBox(-0.1, 1.0, [sign * 0.12, sign * 0.38, -0.16, -0.11], [sign * 0.08, sign * 0.24, -0.12, -0.08]);
  }
  BRIGHT.taperBox(-1.0, 0.8, [-0.05, 0.05, -0.2, -0.15], [-0.03, 0.03, -0.15, -0.11]);
  // Side skirt plates under wing roots
  for (const sign of [-1, 1] as const) {
    TRIM.taperBox(-1.3, 0.6, [sign * 0.35, sign * 0.7, -0.12, 0.08], [sign * 0.3, sign * 0.55, -0.08, 0.1]);
  }

  // ── Twin thruster nacelles (trail anchors ±0.85, z≈-3) ────────────────────
  for (const sign of [-1, 1] as const) {
    const cx = sign * 0.85;
    const hw = 0.28;
    // Boom from wing root / stern to nozzle
    TRIM.beginFacet();
    TRIM.taperBox(-2.85, -1.4, [cx - hw, cx + hw, -0.02, 0.36], [cx - hw * 0.7, cx + hw * 0.7, 0.06, 0.32]);
    TRIM.endFacet();
    HULL.beginFacet();
    HULL.taperBox(-2.55, -1.55, [cx - hw * 0.85, cx + hw * 0.85, 0.06, 0.34], [
      cx - hw * 0.65,
      cx + hw * 0.65,
      0.1,
      0.3,
    ]);
    HULL.endFacet();
    // Pylon into fuselage
    HULL.taperBox(-2.15, -1.35, [sign * 0.35, cx - hw * 0.4, 0.1, 0.32], [sign * 0.4, cx - hw * 0.2, 0.12, 0.3]);
    // Cooling gills
    for (let g = 0; g < 4; g++) {
      const z0 = -2.5 + g * 0.14;
      TRIM.box(cx - hw * 0.6, cx + hw * 0.6, 0.3, 0.35, z0, z0 + 0.05);
    }
    // Nozzle stack
    TRIM.taperBox(-3.0, -2.7, [cx - hw * 0.9, cx + hw * 0.9, 0.02, 0.34], [
      cx - hw * 0.48,
      cx + hw * 0.48,
      0.08,
      0.26,
    ]);
    BRIGHT.taperBox(-2.82, -2.7, [cx - hw * 0.58, cx + hw * 0.58, 0.08, 0.3], [
      cx - hw * 0.42,
      cx + hw * 0.42,
      0.1,
      0.28,
    ]);
    GLOW.beginFacet();
    GLOW.taperBox(-3.12, -2.75, [cx - hw * 0.45, cx + hw * 0.45, 0.1, 0.28], [
      cx - hw * 0.28,
      cx + hw * 0.28,
      0.12,
      0.24,
    ]);
    GLOW.endFacet();
    GLOW.box(cx - 0.07, cx + 0.07, 0.14, 0.22, -3.16, -2.98);
  }

  // Stern bulkhead + number strip
  BRIGHT.beginFacet();
  BRIGHT.taperBox(-2.45, -2.1, [-0.28, 0.28, 0.32, 0.48], [-0.22, 0.22, 0.34, 0.46]);
  BRIGHT.endFacet();
  GLOW.box(-0.12, 0.12, 0.46, 0.52, -2.42, -2.18);
  {
    const n = (id % 4) + 1;
    const span = 0.22;
    const step = span / Math.max(1, n);
    for (let i = 0; i < n; i++) {
      const x0 = -span * 0.5 + i * step + 0.01;
      HULL.box(x0, x0 + step * 0.55, 0.36, 0.44, -2.5, -2.44);
    }
  }

  // Dorsal antenna / sensor mast (aft of canopy)
  TRIM.beginFacet();
  TRIM.taperBox(-1.75, -0.55, [-0.035, 0.035, 0.5, 0.72], [-0.022, 0.022, 0.5, 0.58]);
  TRIM.endFacet();
  HULL.taperBox(-1.55, -0.7, [-0.02, 0.02, 0.62, 0.82], [-0.014, 0.014, 0.55, 0.68]);
  BRIGHT.taperBox(-1.35, -0.9, [-0.01, 0.01, 0.78, 0.88], [-0.008, 0.008, 0.65, 0.72]);
  TRIM.taperBox(-1.25, -1.05, [-0.018, 0.018, 0.82, 1.02], [-0.012, 0.012, 0.84, 0.98]);
  GLOW.box(-0.016, 0.016, 0.98, 1.05, -1.22, -1.08);

  // ── Cockpit tub (seat / grip contract unchanged) ──────────────────────────
  TRIM.taperBox(-0.9, 0.58, [-0.4, 0.4, 0.4, 0.54], [-0.36, 0.36, 0.4, 0.56], true, true, true);
  TRIM.box(-0.4, 0.4, 0.4, 0.54, -0.9, -0.82);
  TRIM.box(-0.36, 0.36, 0.4, 0.56, 0.5, 0.58);
  for (const sign of [-1, 1] as const) {
    TRIM.box(sign * 0.34, sign * 0.44, 0.4, 0.56, -0.9, 0.58);
    HULL.box(sign * 0.32, sign * 0.42, 0.54, 0.58, -0.7, 0.42);
    // Shoulder blister beside pilot
    HULL.beginFacet();
    HULL.taperBox(-0.5, 0.3, [sign * 0.38, sign * 0.62, 0.38, 0.58], [sign * 0.36, sign * 0.56, 0.4, 0.6]);
    HULL.endFacet();
    BRIGHT.box(sign * 0.52, sign * 0.6, 0.58, 0.62, -0.05, 0.15);
  }

  // Seat + backrest
  BRIGHT.taperBox(-0.55, 0.08, [-0.2, 0.2, 0.44, 0.5], [-0.18, 0.18, 0.44, 0.49]);
  TRIM.taperBox(-0.9, -0.48, [-0.26, 0.26, 0.44, 0.82], [-0.22, 0.22, 0.46, 0.74]);
  BRIGHT.taperBox(-0.55, -0.48, [-0.18, 0.18, 0.56, 0.78], [-0.16, 0.16, 0.58, 0.74]);

  // Bubble canopy — taller dome over the pilot
  {
    const bz = 0.55,
      by = 0.54;
    const mz = 0.02,
      my = 0.92;
    const tz = -0.62,
      ty = 1.02;
    const bw = 0.32,
      mw = 0.28,
      tw = 0.2;
    const thick = 0.05;
    TRIM.beginFacet();
    TRIM.quad([-bw, by, bz], [bw, by, bz], [tw, ty, tz], [-tw, ty, tz]);
    TRIM.endFacet();
    for (const sign of [-1, 1] as const) {
      GLASS.quadMirrored(
        sign,
        [bw * 0.9, by + 0.02, bz - 0.02],
        [bw * 0.85, by + thick, bz - 0.02],
        [tw * 0.85, ty - 0.02, tz + 0.02],
        [tw * 0.9, ty - 0.05, tz + 0.02],
      );
      TRIM.quadMirrored(
        sign,
        [bw, by, bz],
        [bw * 0.88, by + thick + 0.02, bz],
        [tw * 0.88, ty - 0.01, tz],
        [tw, ty, tz],
      );
    }
    GLASS.beginFacet();
    GLASS.quad(
      [-bw + 0.04, by + 0.03, bz - 0.03],
      [bw - 0.04, by + 0.03, bz - 0.03],
      [mw - 0.03, my, mz],
      [-mw + 0.03, my, mz],
    );
    GLASS.quad(
      [-mw + 0.03, my, mz],
      [mw - 0.03, my, mz],
      [tw - 0.03, ty - 0.02, tz + 0.03],
      [-tw + 0.03, ty - 0.02, tz + 0.03],
    );
    GLASS.endFacet();
    TRIM.quad([-tw, ty, tz], [tw, ty, tz], [tw * 0.6, 0.54, tz], [-tw * 0.6, 0.54, tz]);
    GLASS.quad(
      [-tw + 0.03, ty - 0.05, tz + 0.02],
      [tw - 0.03, ty - 0.05, tz + 0.02],
      [tw * 0.55, 0.58, tz + 0.03],
      [-tw * 0.55, 0.58, tz + 0.03],
    );
    BRIGHT.quad(
      [-0.04, by + 0.12, bz - 0.05],
      [0.04, by + 0.12, bz - 0.05],
      [0.025, ty - 0.1, tz + 0.05],
      [-0.025, ty - 0.1, tz + 0.05],
    );
  }

  // Yoke + HUD (GRIP_LOCAL)
  TRIM.taperBox(0.12, 0.5, [-0.045, 0.045, 0.46, 0.64], [-0.055, 0.055, 0.54, 0.68]);
  TRIM.box(-0.3, 0.3, 0.655, 0.7, 0.36, 0.48);
  for (const sign of [-1, 1] as const) {
    BRIGHT.box(sign * 0.18, sign * 0.3, 0.645, 0.71, 0.35, 0.5);
  }
  BRIGHT.taperBox(0.48, 0.75, [-0.2, 0.2, 0.52, 0.58], [-0.14, 0.14, 0.46, 0.52]);
  GLOW.taperBox(0.52, 0.72, [-0.12, 0.12, 0.555, 0.58], [-0.1, 0.1, 0.49, 0.52]);

  // Foredeck panel lines
  for (const z of [-1.2, -0.35, 0.55, 1.4, 2.15] as const) {
    let half = 0.45;
    let deck = 0.5;
    for (let i = 0; i < STATIONS.length - 1; i++) {
      const a = STATIONS[i]!;
      const b = STATIONS[i + 1]!;
      if (z >= a.z && z <= b.z) {
        const t = (z - a.z) / (b.z - a.z || 1);
        half = a.half + (b.half - a.half) * t;
        deck = a.deck + (b.deck - a.deck) * t;
        break;
      }
    }
    TRIM.taperBox(z - 0.015, z + 0.015, [-half * 0.85, half * 0.85, deck + 0.01, deck + 0.03], [
      -half * 0.82,
      half * 0.82,
      deck + 0.01,
      deck + 0.03,
    ]);
  }

  // ── Bake ──────────────────────────────────────────────────────────────────
  const mats = makeMaterials(id);
  const group = new Group();
  group.name = `shipMesh${id}`;

  const parts: [Surface, CelMaterialSet, string][] = [
    [HULL, mats.hull, 'hullShell'],
    [TRIM, mats.trim, 'hullTrim'],
    [BRIGHT, mats.bright, 'hullBright'],
    [GLASS, mats.glass, 'hullGlass'],
    [GLOW, mats.glow, 'hullGlow'],
  ];
  let triangles = 0;
  for (const [surf, set, name] of parts) {
    if (surf.triangleCount === 0) continue;
    const mesh = new Mesh(surf.geometry(`${name}${id}`));
    mesh.name = `${name}${id}`;
    applyCel(mesh, set);
    group.add(mesh);
    triangles += surf.triangleCount;
  }

  const seat = new Object3D();
  seat.name = 'seat';
  seat.position.copy(SEAT_LOCAL);
  group.add(seat);

  const grip = new Object3D();
  grip.name = 'grip';
  grip.position.copy(GRIP_LOCAL);
  group.add(grip);

  return {
    group,
    seat,
    grip,
    materials: [mats.hull, mats.trim, mats.bright, mats.glass, mats.glow],
    triangles,
  };
}
