/**
 * Racer factory — AG interceptor mesh + open-world state.
 *
 * Seat/grip contract: parent riders via `getSeat(racer)` / the `"seat"` node —
 * do not hard-code offsets (same as WaveKill boat.ts).
 */

import { Group, Object3D } from 'three';
import { createInputState, type InputState } from '../core/input';
import type { AiPersonality, Racer, RacerId } from '../core/types';
import {
  createShipMesh,
  GRIP_HALF_WIDTH,
  GRIP_LOCAL,
  SEAT_LOCAL,
  SHIP_MESH_SCALE,
  SHIP_MESH_Y,
  type ShipMesh,
} from './shipMesh';
import { createHull } from './hull';
import { createShipState } from './shipPhysics';

/** Mesh handles by racer id — seat/grip lookup for the rider subsystem. */
const meshes = new Map<number, ShipMesh>();

export function createRacer(
  id: RacerId,
  name: string,
  isPlayer: boolean,
  personality: AiPersonality | null = null,
): Racer {
  const root = new Group();
  root.name = name;
  const mesh = createShipMesh(id);
  mesh.group.scale.setScalar(SHIP_MESH_SCALE);
  // Lift mesh so the AG belly sits just under the physics origin (not buried).
  mesh.group.position.y = SHIP_MESH_Y;
  root.add(mesh.group);
  meshes.set(id, mesh);

  const state = createShipState();
  const hull = createHull(state.maxHp);
  state.hp = hull.hp;
  const controls: InputState = createInputState();

  return {
    id,
    isPlayer,
    name,
    root,
    state,
    controls,
    personality,
    hull,
    destroyed: false,
    lap: 0,
    nextCheckpoint: 1,
    progress: 0,
    place: id + 1,
    finished: false,
    finishTime: 0,
    lapTimes: [],
    bestLap: Infinity,
    wrongWay: false,
  };
}

/** Rider attachment point: hips origin on the craft. */
export function getSeat(racer: Racer): Object3D | null {
  return meshes.get(racer.id)?.seat ?? null;
}

/** Handlebar / yoke grip centre. */
export function getGrip(racer: Racer): Object3D | null {
  return meshes.get(racer.id)?.grip ?? null;
}

export function getShipMesh(id: number): ShipMesh | undefined {
  return meshes.get(id);
}

export function syncShipTransform(racer: Racer) {
  const s = racer.state;
  racer.root.position.copy(s.position);
  racer.root.rotation.order = 'YXZ';
  racer.root.rotation.y = s.heading;
  racer.root.rotation.x = s.pitch;
  racer.root.rotation.z = s.roll;
}

export { GRIP_HALF_WIDTH, GRIP_LOCAL, SEAT_LOCAL };
