/**
 * WaveSpace bootstrap — mode select → offline race.
 * Open centreline + gates from WaveKill; free flight; wrong-way HUD.
 * Touch overlay merges with keyboard for mobile / coarse pointers.
 */

import { Game } from './core/game';
import { InputManager } from './core/input';
import { CONFIG } from './core/config';
import type { AiPersonality, GameContext } from './core/types';
import { mergeInputStates, TouchControls } from './core/touchControls';
import { injectTouchStyles } from './core/touchStyles';
import { GameAudio } from './audio/audio';
import { armAudioUnlock } from './audio/unlock';
import { ChaseCamera } from './camera/chaseCamera';
import { HealthBoxField } from './combat/healthBoxes';
import { RocketBoxField } from './combat/rocketBoxes';
import { RocketField } from './combat/rockets';
import { ShipExplosionFx } from './fx/shipExplosion';
import { TrailFx } from './fx/trail';
import { NitroSystem } from './nitro';
import { AiSystem } from './race/ai';
import { RaceStateSystem } from './race/raceState';
import { layoutFromUrl, Track } from './race/track';
import { Riders } from './rider/rider';
import { ShipCollisions } from './ship/shipCollisions';
import { createRacer } from './ship/ship';
import { ModeSelect, type ModeSelectResult } from './ui/ModeSelect';
import { RaceHud } from './ui/hud';

const params = new URLSearchParams(location.search);
const harness = params.get('harness') === '1';

async function boot() {
  injectTouchStyles();
  const gl = document.getElementById('gl') as HTMLCanvasElement;
  const hud = document.getElementById('hud') as HTMLCanvasElement;
  const bootEl = document.getElementById('boot');

  // Arm audio BEFORE mode select so the first tap unlocks iOS/Android audio
  // and builds the synth graph once the context is running.
  const audio = new GameAudio();
  armAudioUnlock(() => {
    void audio.start();
  });

  const modeParam = params.get('mode');
  let mode: ModeSelectResult | 'menu' =
    modeParam === 'circuit' || modeParam === 'combat' || modeParam === 'timeattack'
      ? modeParam
      : 'menu';

  if (mode === 'menu') {
    bootEl?.classList.add('gone');
    const select = new ModeSelect(hud);
    await new Promise<void>((resolve) => {
      const tick = () => {
        select.draw();
        if (select.result) {
          mode = select.result;
          select.dispose();
          resolve();
          return;
        }
        requestAnimationFrame(tick);
      };
      tick();
    });
  }

  // Retry if the menu tap already unlocked; otherwise stay armed for first race tap.
  void audio.start();

  if (mode === 'menu') mode = 'circuit';
  await startOffline(gl, hud, audio, mode, bootEl);
}

async function startOffline(
  gl: HTMLCanvasElement,
  hudCanvas: HTMLCanvasElement,
  audio: GameAudio,
  mode: ModeSelectResult,
  bootEl: HTMLElement | null,
) {
  // Offline modes:
  //   circuit / combat — full pack, nitro, rockets + lock + impact HUD
  //   timeattack       — solo hotlaps, nitro, no AI / weapons
  const combat = mode === 'circuit' || mode === 'combat';
  const solo = mode === 'timeattack';
  const pack = !solo;
  const track = new Track(layoutFromUrl());
  // Player starts last on the grid — chase the pack from the back.
  const aiNames = ['KAIRA', 'NOX', 'PIP', 'REX', 'VEN', 'ASH', 'IO'];
  const aiKinds: AiPersonality[] = ['aggressive', 'clean', 'erratic'];
  const count = solo ? 1 : CONFIG.race.racerCount;
  const racers = [];
  for (let i = 0; i < count; i++) {
    const isPlayer = solo || i === count - 1;
    const name = isPlayer ? 'YOU' : (aiNames[i] ?? `R${i}`);
    const personality: AiPersonality | null = isPlayer
      ? null
      : aiKinds[i % aiKinds.length];
    racers.push(createRacer(i, name, isPlayer, personality));
  }

  const game = new Game(gl, track, racers, { combat, audio, raceMode: mode });
  const input = new InputManager();
  const touch = new TouchControls();
  const race = new RaceStateSystem();
  const ai = new AiSystem();
  const nitro = new NitroSystem(racers);
  const healthBoxes = pack ? new HealthBoxField() : null;
  const rocketBoxes = combat ? new RocketBoxField() : null;
  const riders = new Riders(racers);
  const collisions = pack ? new ShipCollisions() : null;
  const cam = new ChaseCamera();
  const trails = new TrailFx();
  const raceHud = new RaceHud();
  raceHud.touchUi = touch.active;

  window.addEventListener(
    'wheel',
    (e) => {
      e.preventDefault();
      cam.nudgeZoom(Math.sign(e.deltaY));
    },
    { passive: false },
  );

  const doRestart = () => {
    race.restart(game.ctx);
    nitro.reset();
    healthBoxes?.reset(game.ctx);
    rocketBoxes?.reset(game.ctx);
    raceHud.reset();
    cam.snapToTarget();
    hudCanvas.style.pointerEvents = 'none';
    raceHud.clearRestartHover();
  };

  const onHudMove = (ev: PointerEvent) => {
    if (game.ctx.phase !== 'results' && game.ctx.phase !== 'finished') return;
    raceHud.setRestartHover(ev.clientX, ev.clientY);
  };
  const onHudDown = (ev: PointerEvent) => {
    if (game.ctx.phase !== 'results' && game.ctx.phase !== 'finished') return;
    if (raceHud.hitRestart(ev.clientX, ev.clientY)) {
      ev.preventDefault();
      doRestart();
    }
  };
  hudCanvas.addEventListener('pointermove', onHudMove);
  hudCanvas.addEventListener('pointerdown', onHudDown);

  game.add({
    order: 10,
    update(ctx) {
      input.update(ctx.dt);
      touch.update(ctx.dt);
      // Pads during countdown + racing; hide on results so the Race Again button works.
      touch.setVisible(ctx.phase === 'countdown' || ctx.phase === 'racing');
      const controls = touch.active
        ? mergeInputStates(input.state, touch.state)
        : input.state;
      // Only drive once lights are green — matches WaveKill start gate.
      if (ctx.phase === 'racing') {
        Object.assign(ctx.player.controls, controls);
      }
      if (controls.restartPressed) doRestart();
    },
  });

  game.add(track);
  game.add(nitro);
  if (healthBoxes) game.add(healthBoxes);
  if (rocketBoxes) game.add(rocketBoxes);
  if (pack) game.add(ai);
  game.add(race);
  if (combat) game.add(new RocketField());
  if (collisions) game.add(collisions);
  if (combat || pack) game.add(new ShipExplosionFx());
  game.add(riders);
  game.add(trails);
  game.add({
    order: 75,
    update(ctx) {
      // WaveKill: cinematic orbit during countdown / results (not top/high).
      const mode = cam.getMode();
      if (
        (ctx.phase === 'countdown' || ctx.phase === 'results' || ctx.phase === 'finished')
        && mode !== 'top'
        && mode !== 'high'
      ) {
        cam.applyCinematicOrbit(ctx);
      }
    },
  });
  game.add(cam);

  let lastCd = 99;
  let playedGo = false;
  game.setFrameHook((ctx: GameContext) => {
    const engineLive =
      ctx.phase === 'racing' && !ctx.player.finished && !ctx.player.destroyed;
    audio.update(ctx.player.state, ctx.dt, engineLive);
    hudCanvas.style.pointerEvents =
      ctx.phase === 'results' || ctx.phase === 'finished' ? 'auto' : 'none';
    const cd = race.getCountdown();
    if (ctx.phase === 'countdown') {
      const n = Math.ceil(cd);
      if (n !== Math.ceil(lastCd) && n > 0 && n <= 3) audio.playCountdown(n);
      lastCd = cd;
      playedGo = false;
    } else if (!playedGo && race.getGoFlash() > 1) {
      audio.playGo();
      playedGo = true;
    }

    const g = hudCanvas.getContext('2d');
    if (!g) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2.5);
    const cssW = window.innerWidth;
    const cssH = window.innerHeight;
    if (hudCanvas.width !== Math.floor(cssW * dpr) || hudCanvas.height !== Math.floor(cssH * dpr)) {
      hudCanvas.width = Math.floor(cssW * dpr);
      hudCanvas.height = Math.floor(cssH * dpr);
      hudCanvas.style.width = `${cssW}px`;
      hudCanvas.style.height = `${cssH}px`;
    }
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, hudCanvas.width, hudCanvas.height);
    g.save();
    g.scale(dpr, dpr);
    raceHud.draw(g, cssW, cssH, ctx);
    g.restore();
  });

  game.start();
  bootEl?.classList.add('gone');

  if (harness) {
    (window as unknown as { __WAVESPACE__: unknown }).__WAVESPACE__ = {
      ready: true,
      reset: () => doRestart(),
      stats: () => ({
        phase: game.ctx.phase,
        speed: game.ctx.player.state.forwardSpeed,
        place: game.ctx.player.place,
        lap: game.ctx.player.lap,
        wrongWay: game.ctx.player.wrongWay,
        countdown: race.getCountdown(),
        raceTime: game.ctx.raceTime,
        dt: game.ctx.dt,
        systems: (game as unknown as { systems: { order: number; name?: string }[] }).systems?.map(
          (s) => s.name ?? s.order,
        ),
      }),
    };
  }
}

boot().catch((err) => {
  console.error(err);
  const bootEl = document.getElementById('boot');
  if (bootEl) bootEl.textContent = 'BOOT FAILED — see console';
});
