/**
 * WAVESPACE — synthesised Wipeout-style AG audio. No samples.
 *
 * Pitch asymptotes at the limiter; top speed is texture (flutter, grit, air)
 * rather than a linear climb that freezes into one tone.
 */

import { CONFIG } from '../core/config';
import { clamp01 } from '../core/mathx';
import type { AudioAPI, ShipState } from '../core/types';
import { unlockSharedAudio } from './unlock';

function easeIn(t: number, p = 1.6): number {
  const x = clamp01(t);
  return Math.pow(x, p);
}

function easeOut(t: number, p = 1.8): number {
  const x = clamp01(t);
  return 1 - Math.pow(1 - x, p);
}

/** Soft knee: climbs fast early, flattens near 1. */
function asymptote(t: number, knee = 2.4): number {
  const x = clamp01(t);
  return 1 - 1 / (1 + knee * x);
}

export class GameAudio implements AudioAPI {
  private ac: AudioContext | null = null;
  private master!: GainNode;
  private engineGain!: GainNode;
  private sfxGain!: GainNode;
  private musicGain!: GainNode;

  private engineOsc: OscillatorNode[] = [];
  private engineOscGain: GainNode[] = [];
  private engineFilter!: BiquadFilterNode;

  private turbine!: OscillatorNode;
  private turbineGain!: GainNode;
  private turbine2!: OscillatorNode;
  private turbine2Gain!: GainNode;
  private turbFilter!: BiquadFilterNode;

  private buzz!: OscillatorNode;
  private buzzGain!: GainNode;
  private buzzFilter!: BiquadFilterNode;

  private scream!: OscillatorNode;
  private screamGain!: GainNode;

  private airFilter!: BiquadFilterNode;
  private airGain!: GainNode;
  private airSrc: AudioBufferSourceNode | null = null;

  private lfo!: OscillatorNode;
  private lfoGain!: GainNode;
  private flutter!: OscillatorNode;
  private flutterGain!: GainNode;

  private muted = false;
  private started = false;
  private musicTimer: number | null = null;
  private beat = 0;
  private wasBoosting = false;
  private phase = 0;

  async start() {
    if (this.started) return;
    const ac = await unlockSharedAudio();
    if (!ac) return;
    this.ac = ac;
    this.master = ac.createGain();
    this.master.gain.value = CONFIG.audio.masterGain;
    const comp = ac.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 10;
    comp.ratio.value = 3.5;
    comp.attack.value = 0.008;
    comp.release.value = 0.12;
    this.master.connect(comp);
    comp.connect(ac.destination);

    this.engineGain = ac.createGain();
    this.engineGain.gain.value = CONFIG.audio.engineGain;
    this.sfxGain = ac.createGain();
    this.sfxGain.gain.value = CONFIG.audio.sfxGain;
    this.musicGain = ac.createGain();
    this.musicGain.gain.value = CONFIG.audio.musicGain;
    this.engineGain.connect(this.master);
    this.sfxGain.connect(this.master);
    this.musicGain.connect(this.master);

    // Engine chain: layered AG drive → resonant lowpass
    this.engineFilter = ac.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 1400;
    this.engineFilter.Q.value = 4.5;
    this.engineFilter.connect(this.engineGain);

    // Sub drone + odd harmonics (anti-grav core)
    for (const [mul, type, gain] of [
      [1, 'sine', 0.26],
      [2.02, 'sawtooth', 0.09],
      [3.01, 'triangle', 0.06],
      [4.97, 'sine', 0.035],
    ] as const) {
      const o = ac.createOscillator();
      o.type = type;
      o.frequency.value = 62 * mul;
      const g = ac.createGain();
      g.gain.value = gain;
      o.connect(g);
      g.connect(this.engineFilter);
      o.start();
      this.engineOsc.push(o);
      this.engineOscGain.push(g);
    }

    // Mid PWM-ish buzz
    this.buzz = ac.createOscillator();
    this.buzz.type = 'square';
    this.buzz.frequency.value = 95;
    this.buzzGain = ac.createGain();
    this.buzzGain.gain.value = 0.06;
    this.buzzFilter = ac.createBiquadFilter();
    this.buzzFilter.type = 'bandpass';
    this.buzzFilter.frequency.value = 420;
    this.buzzFilter.Q.value = 2.2;
    this.buzz.connect(this.buzzFilter);
    this.buzzFilter.connect(this.buzzGain);
    this.buzzGain.connect(this.engineGain);
    this.buzz.start();

    // Twin turbines — slight detune = living beat at speed
    this.turbFilter = ac.createBiquadFilter();
    this.turbFilter.type = 'bandpass';
    this.turbFilter.frequency.value = 1600;
    this.turbFilter.Q.value = 1.1;
    this.turbFilter.connect(this.engineGain);

    this.turbine = ac.createOscillator();
    this.turbine.type = 'sawtooth';
    this.turbine.frequency.value = 880;
    this.turbineGain = ac.createGain();
    this.turbineGain.gain.value = 0;
    this.turbine.connect(this.turbineGain);
    this.turbineGain.connect(this.turbFilter);
    this.turbine.start();

    this.turbine2 = ac.createOscillator();
    this.turbine2.type = 'sawtooth';
    this.turbine2.frequency.value = 900;
    this.turbine2Gain = ac.createGain();
    this.turbine2Gain.gain.value = 0;
    this.turbine2.connect(this.turbine2Gain);
    this.turbine2Gain.connect(this.turbFilter);
    this.turbine2.start();

    // High-speed scream — only opens above ~0.65 speedFrac
    this.scream = ac.createOscillator();
    this.scream.type = 'triangle';
    this.scream.frequency.value = 2200;
    this.screamGain = ac.createGain();
    this.screamGain.gain.value = 0;
    const screamFilter = ac.createBiquadFilter();
    screamFilter.type = 'highpass';
    screamFilter.frequency.value = 1400;
    screamFilter.Q.value = 0.8;
    this.scream.connect(screamFilter);
    screamFilter.connect(this.screamGain);
    this.screamGain.connect(this.engineGain);
    this.scream.start();

    // Air rush — looped noise through bandpass
    const noiseLen = ac.sampleRate * 2;
    const noiseBuf = ac.createBuffer(1, noiseLen, ac.sampleRate);
    const nd = noiseBuf.getChannelData(0);
    for (let i = 0; i < noiseLen; i++) nd[i] = Math.random() * 2 - 1;
    this.airSrc = ac.createBufferSource();
    this.airSrc.buffer = noiseBuf;
    this.airSrc.loop = true;
    this.airFilter = ac.createBiquadFilter();
    this.airFilter.type = 'bandpass';
    this.airFilter.frequency.value = 1800;
    this.airFilter.Q.value = 0.8;
    this.airGain = ac.createGain();
    this.airGain.gain.value = 0;
    this.airSrc.connect(this.airFilter);
    this.airFilter.connect(this.airGain);
    this.airGain.connect(this.engineGain);
    this.airSrc.start();

    // Slow LFO → filter Q / turbine amplitude wobble
    this.lfo = ac.createOscillator();
    this.lfo.type = 'sine';
    this.lfo.frequency.value = 4.5;
    this.lfoGain = ac.createGain();
    this.lfoGain.gain.value = 0;
    this.lfo.connect(this.lfoGain);
    // Route into turbine gains for amplitude flutter
    this.lfoGain.connect(this.turbineGain.gain);
    this.lfoGain.connect(this.turbine2Gain.gain);
    this.lfo.start();

    // Faster flutter → pitch vibrato on turbines at the limiter
    this.flutter = ac.createOscillator();
    this.flutter.type = 'sine';
    this.flutter.frequency.value = 11;
    this.flutterGain = ac.createGain();
    this.flutterGain.gain.value = 0;
    this.flutter.connect(this.flutterGain);
    this.flutterGain.connect(this.turbine.frequency);
    this.flutterGain.connect(this.turbine2.frequency);
    this.flutterGain.connect(this.scream.frequency);
    this.flutter.start();

    this.started = true;
    this.startMusic();
  }

  private startMusic() {
    if (!this.ac || this.musicTimer != null) return;
    const ac = this.ac;
    const stepMs = 101;
    const tick = () => {
      if (!this.ac || this.muted) {
        this.musicTimer = window.setTimeout(tick, 200);
        return;
      }
      this.beat = (this.beat + 1) % 16;
      const t = ac.currentTime;
      const b = this.beat;

      if (b === 0 || b === 8) {
        const o = ac.createOscillator();
        const g = ac.createGain();
        o.frequency.setValueAtTime(150, t);
        o.frequency.exponentialRampToValueAtTime(38, t + 0.1);
        g.gain.setValueAtTime(0.38, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.14);
        o.connect(g);
        g.connect(this.musicGain);
        o.start(t);
        o.stop(t + 0.15);
      }

      if (b === 4 || b === 12) {
        const buf = ac.createBuffer(1, 1200, ac.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * Math.exp(-i / 280);
        const src = ac.createBufferSource();
        src.buffer = buf;
        const bp = ac.createBiquadFilter();
        bp.type = 'bandpass';
        bp.frequency.value = 2200;
        bp.Q.value = 1.4;
        const hg = ac.createGain();
        hg.gain.setValueAtTime(0.14, t);
        hg.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
        src.connect(bp);
        bp.connect(hg);
        hg.connect(this.musicGain);
        src.start(t);
      }

      {
        const buf = ac.createBuffer(1, 500, ac.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * Math.exp(-i / 90);
        const src = ac.createBufferSource();
        src.buffer = buf;
        const hg = ac.createGain();
        const accent = b % 2 === 1 ? 0.055 : 0.028;
        hg.gain.value = accent * (b % 4 === 3 ? 1.35 : 1);
        src.connect(hg);
        hg.connect(this.musicGain);
        src.start(t);
      }

      const bassNotes = [55, 0, 55, 0, 73, 0, 65, 0, 55, 0, 82, 0, 73, 0, 65, 0];
      const note = bassNotes[b];
      if (note > 0) {
        const o = ac.createOscillator();
        o.type = 'sawtooth';
        o.frequency.value = note;
        const f = ac.createBiquadFilter();
        f.type = 'lowpass';
        f.frequency.setValueAtTime(520, t);
        f.frequency.exponentialRampToValueAtTime(140, t + 0.12);
        f.Q.value = 6;
        const g = ac.createGain();
        g.gain.setValueAtTime(0.12, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + 0.16);
        o.connect(f);
        f.connect(g);
        g.connect(this.musicGain);
        o.start(t);
        o.stop(t + 0.18);
      }

      if (b === 0 || b === 6) {
        const freqs = b === 0 ? [220, 277, 330] : [196, 247, 294];
        for (const freq of freqs) {
          const o = ac.createOscillator();
          o.type = 'sawtooth';
          o.frequency.value = freq;
          const g = ac.createGain();
          g.gain.setValueAtTime(0.035, t);
          g.gain.exponentialRampToValueAtTime(0.001, t + 0.28);
          const f = ac.createBiquadFilter();
          f.type = 'lowpass';
          f.frequency.value = 1800;
          o.connect(f);
          f.connect(g);
          g.connect(this.musicGain);
          o.start(t);
          o.stop(t + 0.3);
        }
      }

      this.musicTimer = window.setTimeout(tick, stepMs);
    };
    tick();
  }

  update(player: ShipState, dt: number, engineLive = true) {
    if (!this.ac || !this.started) return;
    const t = this.ac.currentTime;

    // After the line (or wreck), kill the motor — coasting still has speedFrac.
    if (!engineLive) {
      this.engineGain.gain.setTargetAtTime(0, t, 0.14);
      this.buzzGain.gain.setTargetAtTime(0, t, 0.12);
      this.turbineGain.gain.setTargetAtTime(0, t, 0.12);
      this.turbine2Gain.gain.setTargetAtTime(0, t, 0.12);
      this.screamGain.gain.setTargetAtTime(0, t, 0.1);
      this.airGain.gain.setTargetAtTime(0, t, 0.12);
      this.lfoGain.gain.setTargetAtTime(0, t, 0.12);
      this.flutterGain.gain.setTargetAtTime(0, t, 0.12);
      this.wasBoosting = false;
      return;
    }

    const spd = clamp01(player.speedFrac);
    const thr = clamp01(player.appliedThrottle);
    const boost = player.boosting ? 1 : 0;
    const air = player.airborne ? 1 : 0;
    const slip = clamp01(Math.abs(player.lateralSpeed) / 28);
    const load = clamp01(thr - spd * 0.85 + 0.15); // strain while accelerating
    const coast = clamp01(spd - thr * 0.7); // high speed, light throttle
    const top = easeIn(Math.max(0, spd - 0.55) / 0.45, 1.35); // 0→1 in top band
    const limiter = easeIn(Math.max(0, spd - 0.78) / 0.22, 1.2); // near cap

    this.phase += dt;
    // Pseudo-random blade chatter seed from phase (no Math.random per frame spike)
    const chatter = 0.5 + 0.5 * Math.sin(this.phase * 17.3) * Math.sin(this.phase * 5.1);

    // Pitch asymptotes — early climb is expressive; top end barely rises
    const pitchAmt = asymptote(spd, 2.8);
    const rpm = 55 + pitchAmt * 78 + load * 22 + boost * 48 + air * 8;
    const muls = [1, 2.02, 3.01, 4.97];
    const baseGains = [0.26, 0.09, 0.06, 0.035];
    for (let i = 0; i < this.engineOsc.length; i++) {
      // Slight inharmonic drift at the limiter so harmonics don't lock into a dead chord
      const drift = 1 + limiter * (i === 0 ? 0 : (i % 2 === 0 ? 0.006 : -0.004) * chatter);
      this.engineOsc[i].frequency.setTargetAtTime(rpm * muls[i] * drift, t, 0.045);
      // At top speed, shift energy up the harmonic stack
      const gScale = 1 + top * (i >= 2 ? 0.55 : -0.18) + boost * 0.15;
      this.engineOscGain[i].gain.setTargetAtTime(baseGains[i] * gScale, t, 0.08);
    }

    // Filter: opens with speed, then *narrows and chatters* at the limiter
    const filtOpen = 700 + easeOut(spd) * 2400 + boost * 700 + load * 400;
    const filtTop = filtOpen - limiter * 900 + chatter * limiter * 350;
    this.engineFilter.frequency.setTargetAtTime(filtTop, t, 0.07);
    this.engineFilter.Q.setTargetAtTime(3.2 + load * 2.5 + limiter * 5.5 + boost * 2, t, 0.08);

    // Buzz: grit rises with load + slip; pitch steps in soft plateaus
    const buzzPlateau = Math.floor(spd * 5) / 5;
    this.buzz.frequency.setTargetAtTime(72 + buzzPlateau * 110 + load * 40 + boost * 50, t, 0.06);
    this.buzzFilter.frequency.setTargetAtTime(380 + spd * 520 + slip * 280, t, 0.08);
    this.buzzFilter.Q.setTargetAtTime(1.8 + top * 2.4 + slip * 1.2, t, 0.1);
    this.buzzGain.gain.setTargetAtTime(
      0.03 + load * 0.08 + top * 0.05 + slip * 0.04 + boost * 0.04,
      t,
      0.07,
    );

    // Twin turbines — detuned beat that widens at top speed
    const turbBase = 640 + pitchAmt * 1400 + boost * 520 + air * 180;
    const detune = 8 + top * 28 + limiter * 22 * chatter;
    this.turbine.frequency.setTargetAtTime(turbBase, t, 0.05);
    this.turbine2.frequency.setTargetAtTime(turbBase + detune, t, 0.05);
    this.turbFilter.frequency.setTargetAtTime(1100 + pitchAmt * 2200 + boost * 600, t, 0.08);
    this.turbFilter.Q.setTargetAtTime(0.9 + top * 1.4 + limiter * 1.8, t, 0.1);
    const turbAmp = 0.015 + easeIn(spd, 1.3) * 0.055 + top * 0.04 + boost * 0.07 + air * 0.03;
    this.turbineGain.gain.setTargetAtTime(turbAmp, t, 0.06);
    this.turbine2Gain.gain.setTargetAtTime(turbAmp * 0.85, t, 0.06);

    // Scream layer — only at high speed / boost
    const screamAmt = top * 0.045 + limiter * 0.055 + boost * 0.07;
    this.scream.frequency.setTargetAtTime(1800 + pitchAmt * 1600 + boost * 700 + chatter * 80, t, 0.05);
    this.screamGain.gain.setTargetAtTime(screamAmt, t, 0.07);

    // Air rush dominates the top end (texture instead of pitch)
    this.airFilter.frequency.setTargetAtTime(700 + easeOut(spd) * 3800 + boost * 500 + slip * 400, t, 0.09);
    this.airFilter.Q.setTargetAtTime(0.55 + top * 0.7 + limiter * 0.5, t, 0.1);
    this.airGain.gain.setTargetAtTime(
      easeIn(spd, 1.4) * 0.08 + top * 0.07 + limiter * 0.05 + boost * 0.05 + air * 0.04 + coast * 0.02,
      t,
      0.08,
    );

    // LFO rates & depths — sleepy at cruise, aggressive at the limiter
    this.lfo.frequency.setTargetAtTime(3.2 + top * 4.5 + limiter * 3 + boost * 2, t, 0.1);
    this.lfoGain.gain.setTargetAtTime(top * 0.012 + limiter * 0.018 + boost * 0.01, t, 0.1);
    this.flutter.frequency.setTargetAtTime(7 + top * 10 + limiter * 8 + boost * 5, t, 0.1);
    this.flutterGain.gain.setTargetAtTime(top * 12 + limiter * 28 + boost * 18 + air * 10, t, 0.1);

    // Master engine level — denser at top, not just louder
    const body =
      0.26 +
      thr * 0.4 +
      easeOut(spd) * 0.22 +
      top * 0.12 +
      limiter * 0.08 +
      boost * 0.18 +
      slip * 0.05;
    this.engineGain.gain.setTargetAtTime(this.muted ? 0 : CONFIG.audio.engineGain * body, t, 0.07);

    if (boost && !this.wasBoosting) this.playBoost();
    this.wasBoosting = !!player.boosting;
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : CONFIG.audio.masterGain;
  }

  private beep(freq: number, dur: number, type: OscillatorType = 'square', gain = 0.2) {
    if (!this.ac || this.muted) return;
    const t = this.ac.currentTime;
    const o = this.ac.createOscillator();
    const g = envGain(this.ac, gain, dur);
    o.type = type;
    o.frequency.value = freq;
    o.connect(g);
    g.connect(this.sfxGain);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  private noiseBurst(dur: number, freq: number, q: number, gain: number) {
    if (!this.ac || this.muted) return;
    const ac = this.ac;
    const t = ac.currentTime;
    const n = Math.max(1, Math.floor(ac.sampleRate * dur));
    const buf = ac.createBuffer(1, n, ac.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < n; i++) data[i] = Math.random() * 2 - 1;
    const src = ac.createBufferSource();
    src.buffer = buf;
    const bp = ac.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = freq;
    bp.Q.value = q;
    const g = ac.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(bp);
    bp.connect(g);
    g.connect(this.sfxGain);
    src.start(t);
  }

  playCountdown(n: number) {
    this.beep(520 + n * 60, 0.1, 'square', 0.22);
  }
  playGo() {
    this.beep(220, 0.08, 'sawtooth', 0.2);
    this.beep(440, 0.12, 'sawtooth', 0.18);
    this.beep(880, 0.22, 'square', 0.16);
  }
  playBoost() {
    if (!this.ac || this.muted) return;
    const ac = this.ac;
    const t = ac.currentTime;
    const o = ac.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(180, t);
    o.frequency.exponentialRampToValueAtTime(1400, t + 0.22);
    const g = envGain(ac, 0.2, 0.28);
    o.connect(g);
    g.connect(this.sfxGain);
    o.start(t);
    o.stop(t + 0.3);
    this.noiseBurst(0.25, 2400, 0.6, 0.12);
    this.beep(960, 0.08, 'square', 0.1);
  }
  playWeapon() {
    this.beep(140, 0.08, 'square', 0.18);
    this.beep(420, 0.06, 'sawtooth', 0.12);
  }
  playHit() {
    this.noiseBurst(0.22, 280, 1.2, 0.28);
    this.beep(70, 0.18, 'sawtooth', 0.24);
  }
  playExplode() {
    if (!this.ac || this.muted) return;
    this.noiseBurst(0.55, 120, 0.7, 0.42);
    this.noiseBurst(0.35, 520, 0.9, 0.22);
    this.noiseBurst(0.28, 1800, 0.55, 0.14);
    this.beep(48, 0.32, 'sawtooth', 0.32);
    this.beep(90, 0.18, 'square', 0.16);
    this.beep(220, 0.1, 'sawtooth', 0.1);
  }
  playLap() {
    this.beep(660, 0.08, 'square', 0.14);
    this.beep(990, 0.12, 'square', 0.16);
  }
  playFinish() {
    this.beep(523, 0.12, 'sawtooth', 0.16);
    this.beep(659, 0.12, 'sawtooth', 0.16);
    this.beep(784, 0.14, 'sawtooth', 0.16);
    this.beep(1046, 0.28, 'square', 0.14);
  }
  checkpoint() {
    this.beep(880, 0.06, 'square', 0.12);
    this.beep(1320, 0.05, 'triangle', 0.08);
  }

  dispose() {
    if (this.musicTimer != null) clearTimeout(this.musicTimer);
    try {
      this.airSrc?.stop();
    } catch {
      /* ignore */
    }
    try {
      this.ac?.close();
    } catch {
      /* ignore */
    }
    this.ac = null;
    this.started = false;
  }
}

function envGain(ac: AudioContext, peak: number, dur: number): GainNode {
  const g = ac.createGain();
  const t = ac.currentTime;
  g.gain.setValueAtTime(peak, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  return g;
}
